@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Nunito:wght@500;600;700;800;900&display=swap');
:root{--ink:#f6f1e7;--muted:#9c9b9b;--panel:#20232b;--panel2:#282b34;--line:#393b43;--yellow:#f2c75c;--orange:#f08b62;--mint:#a9d8bd;--bg:#171a20}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Nunito,system-ui,sans-serif;min-height:100vh;display:flex;justify-content:center;align-items:center;padding:24px;background-image:radial-gradient(ellipse at 18% 0%,#252a31 0,transparent 36%),radial-gradient(ellipse at 95% 100%,#27231f 0,transparent 32%)}button{font:inherit;color:inherit}.game-shell{width:min(1200px,100%)}.topbar{height:56px;display:flex;align-items:center;justify-content:space-between;margin-bottom:16px}.brand{display:flex;gap:10px;align-items:center;color:var(--ink);text-decoration:none;font-weight:900;letter-spacing:1.6px;font-size:16px}.brand b{color:var(--yellow)}.brand-mark{background:#f2c75c;color:#24242a;width:30px;height:30px;border-radius:10px;display:grid;place-items:center;font-size:18px;transform:rotate(-8deg)}.top-meta{display:flex;align-items:center;gap:16px}.pill{font:10px 'DM Mono',monospace;letter-spacing:1.1px;color:#dfd7c6}.pill i,.live-dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:#a9d8bd;margin-right:7px;box-shadow:0 0 10px #a9d8bd66}.sound-label{font:9px 'DM Mono',monospace;color:#777a81;letter-spacing:1.4px}.icon-btn,.pause-btn{border:1px solid var(--line);background:#242730;border-radius:10px;width:36px;height:36px;cursor:pointer;color:var(--yellow)}.game-layout{display:grid;grid-template-columns:minmax(0,1fr) 286px;gap:14px}.arena-wrap{position:relative;min-width:0;height:min(70vh,680px);min-height:500px;background:#caba68;border-radius:16px;overflow:hidden;border:1px solid #47433a;box-shadow:0 20px 70px #0005}.arena-wrap canvas{width:100%;height:100%;display:block}.hud{position:absolute;inset:0 0 auto;padding:18px 20px 0;display:flex;flex-wrap:wrap;justify-content:space-between;pointer-events:none;text-shadow:0 2px 6px #272317a6}.hud-left,.hud-right{display:flex;align-items:center;gap:12px}.level-chip{height:48px;width:46px;background:#27262ad9;border:1px solid #ffffff25;border-radius:10px;display:flex;flex-direction:column;align-items:center;justify-content:center}.level-chip small{font:8px 'DM Mono',monospace;color:#d4be79;letter-spacing:1px}.level-chip strong{font-size:20px;line-height:20px}.wave-info{display:flex;flex-direction:column;gap:3px}.wave-info strong{font-size:12px;letter-spacing:1.3px}.wave-info span{font:9px 'DM Mono',monospace;letter-spacing:1px;color:#f5e8ca}.stat{display:grid;grid-template-columns:16px auto;column-gap:4px;align-items:center}.stat span{color:var(--yellow);grid-row:span 2;font-size:14px}.stat b{font:15px 'DM Mono',monospace}.stat small{font:7px 'DM Mono',monospace;color:#f1e6cb;letter-spacing:.8px}.pause-btn{pointer-events:auto;background:#292a2ecc;border-color:#ffffff30;font-size:12px;color:#f7ecd0}.health-row,.xp-row{width:100%;display:flex;align-items:center;gap:9px;margin-top:12px;font:8px 'DM Mono',monospace;letter-spacing:.8px}.health-row{margin-top:13px}.health-label{width:29px;color:#fff4da}.bar{height:7px;background:#282722ad;border-radius:6px;flex:1;overflow:hidden;border:1px solid #ffffff20}.bar i{display:block;width:100%;height:100%;background:#ed876d;border-radius:6px;transition:width .2s}.health-row b,.xp-row b{font-size:9px;min-width:55px;text-align:right}.xp-row{margin-top:6px}.xp-row>span{width:29px;font-size:7px;color:#fff4da}.xp-bar i{background:#a6d9bb}.overlay{position:absolute;inset:0;background:#1718207a;display:grid;place-items:center;backdrop-filter:blur(2px);z-index:3}.modal{position:relative;text-align:center;background:#20232bed;border:1px solid #ffffff1b;border-radius:18px;padding:31px 38px;box-shadow:0 20px 80px #0007;width:min(410px,90%)}.eyebrow{font:9px 'DM Mono',monospace;letter-spacing:1.8px;color:var(--yellow);margin-bottom:14px}.sparkle{font-size:12px;margin:0 6px}.modal h1,.modal h2{margin:0;color:#f7f1e5;font-size:55px;line-height:.84;letter-spacing:-2px;font-weight:900}.modal h1 em,.modal h2 em{font-style:normal;color:var(--yellow)}.intro-copy{font-size:13px;line-height:1.65;color:#c5c2bb;margin:15px 0 18px}.intro-copy b{color:#fff}.plane-sticker{position:absolute;right:27px;top:106px;color:#a8d7bd;font-size:31px;transform:rotate(-16deg)}.plane-sticker span{position:absolute;font-size:12px;right:-5px;top:-3px;color:var(--yellow)}.primary-btn{border:0;border-radius:9px;padding:13px 18px;background:var(--yellow);color:#29262a;font:900 11px Nunito,sans-serif;letter-spacing:1.1px;cursor:pointer;box-shadow:0 4px 0 #b78737;transition:transform .12s,filter .12s}.primary-btn:hover{filter:brightness(1.08);transform:translateY(-1px)}.primary-btn span{font-size:16px;margin-left:12px}.control-hint{margin-top:18px;color:#95959a;font:8px 'DM Mono',monospace;letter-spacing:.6px}.control-hint span{color:var(--mint);font-size:11px}.control-hint i{padding:0 6px;color:#5a5c62}.side-panel{background:var(--panel);border:1px solid #343740;border-radius:15px;padding:20px 18px 13px;display:flex;flex-direction:column;min-height:min(70vh,680px)}.panel-kicker,.section-title{font:9px 'DM Mono',monospace;letter-spacing:1.3px;color:#aeb0b6}.panel-kicker{display:flex;justify-content:space-between;margin-bottom:14px}.panel-kicker span,.section-title span{color:var(--yellow)}.run-card{background:#292c35;border:1px solid #3c3e47;border-radius:10px;padding:12px 12px 10px}.card-top{display:flex;justify-content:space-between;color:#92949a;font:8px 'DM Mono',monospace;letter-spacing:1px}.live-dot{width:6px;height:6px;margin:0;background:#666}.live-dot.active{background:#9cd8ae;box-shadow:0 0 8px #9cd8ae}.run-state{font-size:14px;font-weight:900;margin:8px 0 10px;letter-spacing:.3px}.progress-line{height:4px;background:#41434a;border-radius:4px;overflow:hidden}.progress-line i{display:block;width:0;height:100%;background:var(--yellow);transition:width .3s}.progress-label{display:flex;justify-content:space-between;font:8px 'DM Mono',monospace;color:#a5a6aa;margin-top:7px;letter-spacing:.5px}.progress-label span:last-child{color:var(--yellow)}.side-section{margin-top:18px}.section-title{display:flex;justify-content:space-between;margin-bottom:10px}.section-title span{font-size:8px}.spec{display:flex;justify-content:space-between;font-size:11px;color:#c4c3c0;padding:5px 1px;border-bottom:1px solid #ffffff0a}.spec b{font:11px 'DM Mono',monospace;color:#eee7d9}.level-section{margin-top:18px}.level-list{display:grid;grid-template-columns:repeat(6,1fr);gap:5px}.level-tile{height:26px;border-radius:6px;background:#2c2f38;color:#8f9198;display:grid;place-items:center;font:9px 'DM Mono',monospace;border:1px solid #3b3e46}.level-tile.done{color:#202429;background:#a9d8bd;border-color:#a9d8bd}.level-tile.current{color:#29262a;background:var(--yellow);border-color:var(--yellow);box-shadow:0 0 10px #f2c75c45}.tip-card{margin-top:auto;background:#2a2d34;border:1px solid #3a3d43;border-radius:9px;padding:11px 10px;display:flex;gap:10px}.tip-icon{font-size:19px;color:var(--yellow)}.tip-card b{font:8px 'DM Mono',monospace;letter-spacing:1px;color:var(--yellow)}.tip-card p{font-size:10px;line-height:1.4;color:#c6c4be;margin:4px 0 0}.panel-footer{display:flex;justify-content:space-between;font:7px 'DM Mono',monospace;color:#74777e;letter-spacing:.9px;padding-top:12px}.panel-footer span:last-child{color:var(--yellow)}.footer{height:39px;display:flex;align-items:end;justify-content:space-between;color:#73767d;font:8px 'DM Mono',monospace;letter-spacing:1px}.footer b{color:#95c7a8;font-size:7px}.hidden{display:none!important}.upgrade-modal{width:min(480px,92%);padding:26px 26px}.upgrade-modal h2{font-size:38px;line-height:.9}.upgrade-sub{font-size:11px;color:#aaa9a5;margin:10px 0 17px}.upgrade-choices{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.upgrade-card{background:#2b2e37;border:1px solid #444751;border-radius:11px;padding:13px 10px;text-align:left;cursor:pointer;min-height:128px;transition:.15s}.upgrade-card:hover{border-color:var(--yellow);transform:translateY(-3px);background:#34353b}.upgrade-icon{font-size:23px;color:var(--yellow);margin-bottom:7px}.upgrade-card b{display:block;font-size:11px;line-height:1.15}.upgrade-card p{margin:5px 0 0;color:#aaa9a5;font-size:9px;line-height:1.35}.pause-modal h2,.end-modal h2{font-size:38px;margin-bottom:20px}.end-stats{display:flex;justify-content:center;gap:22px;margin:17px 0 21px;color:#c7c4bd;font:9px 'DM Mono',monospace}.end-stats b{color:var(--yellow);font-size:14px;display:block;margin-bottom:4px}.touch-controls{display:none}.dpad{display:grid;grid-template-columns:repeat(3,44px);grid-template-rows:repeat(2,42px);gap:5px}.dpad button{border:1px solid #ffffff25;background:#272a31d9;border-radius:9px;color:#f2d574;font-size:15px;touch-action:none}.dpad button:first-child{grid-column:2}.dpad button:nth-child(2){grid-column:1;grid-row:2}.dpad button:nth-child(3){grid-column:2;grid-row:2}.dpad button:nth-child(4){grid-column:3;grid-row:2}.touch-note{font:7px 'DM Mono',monospace;color:#aaa;letter-spacing:1px;text-align:center;margin-top:5px}
@media(max-width:850px){body{padding:12px}.game-layout{grid-template-columns:minmax(0,1fr) 240px;gap:10px}.side-panel{padding:16px 13px}.arena-wrap{min-height:480px}.topbar{margin-bottom:10px}.side-section{margin-top:14px}}
@media(max-width:650px){body{padding:8px;align-items:flex-start}.topbar{height:40px}.sound-label{display:none}.brand{font-size:13px}.game-layout{display:flex;flex-direction:column}.arena-wrap{height:calc(100dvh - 185px);min-height:410px;max-height:680px}.side-panel{min-height:unset;padding:12px 13px}.panel-kicker{margin-bottom:8px}.run-card{padding:8px 10px}.run-state{margin:5px 0}.side-section{margin-top:10px}.spec{padding:3px 1px}.tip-card,.panel-footer{display:none}.level-section{margin-top:10px}.level-list{grid-template-columns:repeat(12,1fr);gap:3px}.level-tile{height:22px}.footer{height:26px;font-size:6px}.touch-controls{display:flex;position:fixed;left:13px;bottom:15px;align-items:center;z-index:2;opacity:.8}.intro-modal{padding:26px 21px}.modal h1{font-size:48px}.plane-sticker{right:18px;top:92px}.control-hint{font-size:7px}.upgrade-choices{gap:5px}.upgrade-card{padding:10px 7px;min-height:118px}.upgrade-card b{font-size:10px}.upgrade-card p{font-size:8px}}

(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const $ = id => document.getElementById(id);
  const overlays = $('overlay');
  const floors = [
    ['YELLOW HALLS','A maze of lemon wallpaper and bad ideas.'],['THE WET CARPET','Mind the puddles. They mind you back.'],['OFFICE AFTER HOURS','The staplers have unionized.'],['POOLROOMS','Chlorine, tiles, and something in lane 4.'],['THE INFINITE MALL','Sale! Nowhere to go, nowhere to hide.'],['RED LAMPS','A little mood lighting. A lot of trouble.'],['THE FUN ZONE','The clown says you look delicious.'],['MAINTENANCE','Hot pipes. Cold welcomes.'],['THE HOTEL WING','Please do not feed the wallpaper.'],['THE STATIC FLOOR','The TVs are all tuned to YOU.'],['THE EXIT MAZE','Every door is the wrong door.'],['THE WAY OUT?','One last flight. Probably.']
  ];
  const enemyTypes = [
    {name:'DUST BUNNY',color:'#84674d',hp:2,speed:41,size:12,damage:7,xp:1},
    {name:'WALL GREMLIN',color:'#e77a58',hp:3,speed:29,size:16,damage:10,xp:2},
    {name:'BAD VIBE',color:'#514b69',hp:5,speed:21,size:20,damage:13,xp:3},
    {name:'PAPER WRAITH',color:'#d9ddd0',hp:2,speed:69,size:10,damage:8,xp:1}
  ];
  const perks = [
    {icon:'✦',name:'JUICIER JUICE',desc:'+25% plane damage',apply:p=>p.damage*=1.25,stat:'damage'},
    {icon:'➤',name:'TURBO TAIL',desc:'+15% move speed',apply:p=>p.speed*=1.15,stat:'speed'},
    {icon:'♡',name:'DUCT TAPE',desc:'Patch up 35 hull',apply:p=>p.hp=Math.min(p.maxHp,p.hp+35),stat:'heal'},
    {icon:'⌁',name:'WINGMAN',desc:'Add a helpful orbiting buddy',apply:p=>p.wingmen++,stat:'wing'},
    {icon:'◉',name:'BIGGER BULLETS',desc:'+1 projectile damage',apply:p=>p.damage+=1,stat:'damage'},
    {icon:'☂',name:'PILOT GOGGLES',desc:'+20 maximum hull',apply:p=>{p.maxHp+=20;p.hp+=20},stat:'armor'},
    {icon:'↯',name:'QUICK TRIGGER',desc:'Fire 20% faster',apply:p=>p.fireRate*=.8,stat:'damage'},
    {icon:'✧',name:'SUGAR RUSH',desc:'Move 10% faster & heal 10',apply:p=>{p.speed*=1.1;p.hp=Math.min(p.maxHp,p.hp+10)},stat:'speed'}
  ];
  const state = {mode:'title',wave:0,waveTime:0,intermission:0,entities:[],bullets:[],enemyBullets:[],pickups:[],particles:[],kills:0,scrap:0,elapsed:0,spawnTimer:0,keys:{},pointer:null,screenShake:0,killGoal:0};
  const player = {x:0,y:0,r:14,hp:100,maxHp:100,speed:210,damage:1,fireRate:.62,fire:0,wingmen:0,invuln:0,xp:0,level:1,angle:0};
  let W=800,H=600,dpr=1,last=0, soundOn=false, audio;
  const roomColors = [['#c8b66d','#d5c87e','#baaa60','#9c884d'],['#7f7970','#b2aea0','#68635b','#554c45'],['#78745e','#b4ad7b','#575344','#3b3c33'],['#8ac4c3','#b7d9d4','#66a6a8','#508486'],['#bd956c','#e7c592','#94714f','#705544'],['#8d625e','#bd8a7b','#694b4c','#513d42'],['#d98d69','#f2bd85','#ad665c','#8d4e52'],['#85836f','#beb497','#696955','#514f45'],['#918d83','#c3b9a2','#73685c','#514d4a'],['#7d7e85','#aeb0b6','#555762','#41434c'],['#b28a60','#ddbe84','#846648','#5f4b39'],['#aaa18b','#e2d4b0','#756f65','#4c4a49']];
  function resize(){const rect=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);W=rect.width;H=rect.height;canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);if(!player.x){player.x=W/2;player.y=H/2}}
  new ResizeObserver(resize).observe(canvas); resize();
  function rand(a,b){return a+Math.random()*(b-a)}
  function pick(a){return a[Math.floor(Math.random()*a.length)]}
  function sound(freq=420,duration=.06,type='sine'){if(!soundOn)return;try{audio??=new AudioContext();const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(.035,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration)}catch{}}
  function showModal(id){for(const node of overlays.querySelectorAll('.modal'))node.classList.toggle('hidden',node.id!==id);overlays.classList.remove('hidden')}
  function hideOverlay(){overlays.classList.add('hidden')}
  function reset(){Object.assign(state,{mode:'play',wave:0,waveTime:0,intermission:0,entities:[],bullets:[],enemyBullets:[],pickups:[],particles:[],kills:0,scrap:0,elapsed:0,spawnTimer:0,screenShake:0,killGoal:0});Object.assign(player,{x:W/2,y:H/2,r:14,hp:100,maxHp:100,speed:210,damage:1,fireRate:.62,fire:0,wingmen:0,invuln:0,xp:0,level:1,angle:0});startWave(0);hideOverlay();updateUI()}
  function startWave(n){state.wave=n;state.waveTime=0;state.spawnTimer=.45;state.killGoal=7+n*2+(n%4===3?1:0);state.mode='play';$('runState').textContent='IN THE THICK OF IT';$('liveDot').classList.add('active');$('tipTitle').textContent=n%4===3?'BOSS WARNING':'PILOT TIP';$('tipText').textContent=n%4===3?'Big trouble incoming! Circle-strafe and keep your nose up.':pick(['Keep moving. The halls are full of uninvited guests.','Your pea-shooter is automatic. You just steer!','Scrap is shiny. Shiny is good.','Try not to test if the walls are solid.']);updateUI()}
  function startGame(){reset()}
  function chooseUpgrade(perk){perk.apply(player);state.intermission=0;if(state.wave>=floors.length-1){state.mode='win';finish(true);return}startWave(state.wave+1)}
  function finish(win){state.mode=win?'win':'dead';$('liveDot').classList.remove('active');$('runState').textContent=win?'OUT (ALLEGEDLY)':'NEEDS A TOW';$('endEyebrow').textContent=win?'FLIGHT COMPLETE':'FLIGHT LOG';$('endTitle').textContent=win?'YOU MADE IT!':'PARKED FOR GOOD';$('endCopy').textContent=win?'You flew through all 12 floors. The sky has never looked so suspicious.':'The Backrooms win this round. Your tiny plane deserves a snack.';$('endStats').innerHTML=`<div><b>${state.wave+1}/12</b>FLOORS</div><div><b>${state.kills}</b>BONKS</div><div><b>${state.scrap}</b>SCRAP</div>`;showModal('endModal')}
  function upgrade(){state.mode='upgrade';$('runState').textContent='TUNE-UP TIME';$('liveDot').classList.remove('active');const choices=[];while(choices.length<3){const p=pick(perks);if(!choices.includes(p))choices.push(p)}$('upgradeChoices').innerHTML='';for(const p of choices){const card=document.createElement('button');card.className='upgrade-card';card.innerHTML=`<div class="upgrade-icon">${p.icon}</div><b>${p.name}</b><p>${p.desc}</p>`;card.onclick=()=>{sound(600,.08);chooseUpgrade(p)};$('upgradeChoices').appendChild(card)}showModal('upgradeModal');updateUI()}
  function spawnEnemy(boss=false){const side=Math.floor(rand(0,4));let x=side===0?-25:side===1?W+25:rand(0,W),y=side===2?-25:side===3?H+25:rand(0,H);const type=boss?{name:'THE HALL MONITOR',color:'#ed665e',hp:28+state.wave*4,speed:23,size:29,damage:18,xp:12}:pick(enemyTypes);const mult=1+state.wave*.17;state.entities.push({x,y,r:type.size,hp:type.hp*mult,maxHp:type.hp*mult,speed:type.speed*(1+state.wave*.025),damage:type.damage*(1+state.wave*.06),color:type.color,name:type.name,xp:type.xp,boss,phase:rand(0,6.28),shot:rand(2,5)})}
  function fireAt(target,fromX=player.x,fromY=player.y,damage=player.damage){const a=Math.atan2(target.y-fromY,target.x-fromX);state.bullets.push({x:fromX,y:fromY,vx:Math.cos(a)*460,vy:Math.sin(a)*460,r:4,damage,life:1.15});player.angle=a;sound(530+Math.random()*100,.035,'triangle')}
  function nearest(x=player.x,y=player.y){let best=null,dist=Infinity;for(const e of state.entities){const d=(e.x-x)**2+(e.y-y)**2;if(d<dist){dist=d;best=e}}return best}
  function addParticle(x,y,color,n=5){for(let i=0;i<n;i++)state.particles.push({x,y,vx:rand(-90,90),vy:rand(-90,90),life:rand(.2,.55),max:.55,color,r:rand(2,4)})}
  function hurt(amount){if(player.invuln>0)return;player.hp-=Math.max(1,amount);player.invuln=.55;state.screenShake=7;sound(140,.12,'square');if(player.hp<=0){player.hp=0;finish(false)}}
  function update(dt){if(state.mode!=='play')return;state.elapsed+=dt;state.waveTime+=dt;player.invuln=Math.max(0,player.invuln-dt);state.screenShake=Math.max(0,state.screenShake-dt*28);
    let dx=(state.keys.right?1:0)-(state.keys.left?1:0),dy=(state.keys.down?1:0)-(state.keys.up?1:0);if(state.pointer){dx+=state.pointer.dx;dy+=state.pointer.dy}const len=Math.hypot(dx,dy);if(len){dx/=len;dy/=len;player.x+=dx*player.speed*dt;player.y+=dy*player.speed*dt;player.angle=Math.atan2(dy,dx)}player.x=Math.max(22,Math.min(W-22,player.x));player.y=Math.max(30,Math.min(H-22,player.y));
    const bossWave=state.wave%4===3;const maxTime=24+state.wave*.45;
    if(state.spawnTimer<=0&&state.waveTime<maxTime&&state.entities.filter(e=>!e.boss).length<8+Math.floor(state.wave/3)){spawnEnemy(false);state.spawnTimer=Math.max(.35,1.05-state.wave*.035)}else state.spawnTimer-=dt;
    if(bossWave&&state.waveTime>2&&!state.entities.some(e=>e.boss))spawnEnemy(true);
    const target=nearest();player.fire-=dt;if(target&&player.fire<=0){fireAt(target);player.fire=player.fireRate;for(let i=0;i<player.wingmen;i++){const a=state.elapsed*1.6+i*Math.PI*2/player.wingmen;const wx=player.x+Math.cos(a)*29,wy=player.y+Math.sin(a)*29;fireAt(target,wx,wy,player.damage*.55)}}
    for(const e of state.entities){const a=Math.atan2(player.y-e.y,player.x-e.x),d=Math.hypot(player.x-e.x,player.y-e.y);e.phase+=dt*4;if(d>e.r+player.r+4){e.x+=Math.cos(a)*e.speed*dt;e.y+=Math.sin(a)*e.speed*dt}else hurt(e.damage*dt*2);if(e.boss){e.shot-=dt;if(e.shot<=0&&d<260){state.enemyBullets.push({x:e.x,y:e.y,vx:Math.cos(a)*150,vy:Math.sin(a)*150,r:6,life:3,damage:9});e.shot=2.3}}}
    for(const b of state.bullets){b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;for(const e of state.entities){if(!b.dead&&Math.hypot(e.x-b.x,e.y-b.y)<e.r+b.r){e.hp-=b.damage;b.dead=true;addParticle(b.x,b.y,'#ffe07d',2);if(e.hp<=0){state.kills++;state.scrap+=e.boss?8:1;state.pickups.push({x:e.x,y:e.y,r:e.boss?9:5,xp:e.xp,value:e.boss?5:1,color:e.boss?'#ffd66c':'#a9d8bd'});addParticle(e.x,e.y,e.color,10);sound(190,.08,'sawtooth')}}}state.bullets=state.bullets.filter(b=>!b.dead&&b.life>0&&b.x>-30&&b.x<W+30&&b.y>-30&&b.y<H+30);
